	ld hl,0a11ch		;88c9   ; Color de la imagen -> VRAM 0x2000 (los tres tercios)
	ld de,02000h		;88cc
	ld bc,01800h		;88cf
	call 0005ch		;88d2   ; BIOS LDIRVM - Block transfers to VRAM from memory
	call 00044h		;88d5   ; BIOS ENASCR - Displays the screen | Ya esta la imagen entera: encender pantalla
	ei			;88d8
	ret			;88d9   ; Vuelve al cargador, que seguira con el bloque del juego

